uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float waves : 0.5 .. 8.0 = 3.0;
uniform float amplitude : 0.01 .. 0.2 = 0.08;
uniform vec3 tint : color = 0.15, 0.45, 0.85;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
}
vec3 shade(Led led) {
  // height along lamp [0..1] from bottom (led.pos.y: 0..0.30)
  fixed h = fixed(led.pos.y) / fixed(0.30);
  // horizontal radius: led.pos.x/z radius is 0.08; use atan2 for angle in turns
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  // sinusoidal height displacement: a sine wave along the height, advected by ph
  fixed disp = sin(fixed(2.0) * fixed(waves) * h + ph) * fixed(amplitude);
  // displaced height, wrapped to [0..1]
  fixed h2 = h + disp;
  h2 = fract(h2);
  // horizontal phase that rolls with the wave
  fixed hphase = fract(ang - ph);
  // combine vertical displacement with horizontal phase to make a rolling swell
  float band = smoothstep(fixed(0.06), fixed(0.0), abs(hphase - fixed(0.5)));
  // tint modulated by height position (deeper = more blue)
  fixed hue = fract(h2 * fixed(2.0) + ph);
  vec3 col = hsv2rgb(hue, fixed(0.8), fixed(1.0));
  return col;
}

